@dataclass
class Diagnostic:
    kind: str
    severity: str
    path: str
    message: str

    def to_dict(self) -> dict[str, Any]:
        return {"kind": self.kind, "severity": self.severity, "path": self.path, "message": self.message}


@dataclass
class RewriteResult:
    format: str
    safe: bool
    changed: bool
    original_text: str
    new_text: str | None
    diagnostics: list[Diagnostic] = field(default_factory=list)

    def unsafe_diagnostics(self) -> list[Diagnostic]:
        return [d for d in self.diagnostics if d.severity == UNSAFE]

    def to_report(self) -> dict[str, Any]:
        return {
            "format": self.format,
            "safe": self.safe,
            "changed": self.changed,
            "diagnostics": [d.to_dict() for d in self.diagnostics],
        }


class _CycleGuard:
    """Recursion guard so a genuine cyclic object graph cannot hang the walker."""

    def __init__(self) -> None:
        self._stack: set[int] = set()

    def enter(self, node: Any) -> bool:
        """Return True if entering ``node`` would revisit an ancestor (a cycle)."""
        return id(node) in self._stack

    def push(self, node: Any) -> None:
        self._stack.add(id(node))

    def pop(self, node: Any) -> None:
        self._stack.discard(id(node))


def _residual_and_new_reference_diagnostics(
    original_text: str, new_text: str, mapping: dict[str, str]
) -> list[Diagnostic]:
    diagnostics: list[Diagnostic] = []
    for old, new in mapping.items():
        residual_count = new_text.count(old)
        if residual_count:
            diagnostics.append(
                Diagnostic(
                    kind="residual_old_reference",
                    severity=WARNING,
                    path="<document>",
                    message=(
                        f"{residual_count} occurrence(s) of {old!r} remain in the output "
                        "(likely inside a key name, comment, or unsupported-tag node, "
                        "none of which this tool rewrites)."
                    ),
                )
            )
        preexisting_new = original_text.count(new)
        if preexisting_new:
            diagnostics.append(
                Diagnostic(
                    kind="unexpected_new_reference",
                    severity=WARNING,
                    path="<document>",
                    message=(
                        f"{preexisting_new} occurrence(s) of the replacement value {new!r} "
                        "already existed in the input before this run touched it; verify "
                        "these are not conflated with references this run introduced."
                    ),
                )
            )
    return diagnostics


