def _toml_replace_string_item(item: TomlString, new_value: str) -> TomlString:
    new_item = TomlString.from_raw(new_value, type_=item.type)
    new_item.trivia.indent = item.trivia.indent
    new_item.trivia.comment_ws = item.trivia.comment_ws
    new_item.trivia.comment = item.trivia.comment
    new_item.trivia.trail = item.trivia.trail
    return new_item


def _toml_walk(node: Any, mapping: dict[str, str], path: str, diagnostics: list[Diagnostic], guard: _CycleGuard) -> None:
    if guard.enter(node):
        diagnostics.append(Diagnostic("alias_cycle", UNSAFE, path, "cyclic structure detected while walking TOML document"))
        return
    if hasattr(node, "keys") and hasattr(node, "__setitem__") and not isinstance(node, str):
        guard.push(node)
        for key in list(node.keys()):
            value = node[key]
            child_path = f"{path}.{key}" if path else str(key)
            if isinstance(value, TomlString):
                _toml_maybe_replace_leaf(node, key, value, mapping, child_path, diagnostics)
            else:
                _toml_walk(value, mapping, child_path, diagnostics, guard)
        guard.pop(node)
    elif isinstance(node, list) and not isinstance(node, str):
        guard.push(node)
        for index, value in enumerate(node):
            child_path = f"{path}[{index}]"
            if isinstance(value, TomlString):
                _toml_maybe_replace_leaf(node, index, value, mapping, child_path, diagnostics)
            else:
                _toml_walk(value, mapping, child_path, diagnostics, guard)
        guard.pop(node)


def _toml_maybe_replace_leaf(container: Any, key: Any, item: TomlString, mapping: dict[str, str], path: str, diagnostics: list[Diagnostic]) -> None:
    text = str(item)
    new_text = text
    hit = False
    for old, new in mapping.items():
        if old in new_text:
            new_text = new_text.replace(old, new)
            hit = True
    if not hit:
        return
    replaced_item = _toml_replace_string_item(item, new_text)
    container[key] = replaced_item
    post = str(container[key])
    if post != new_text:
        diagnostics.append(
            Diagnostic("type_changing_substitution", UNSAFE, path, "TOML string item lost its scalar-string type after replacement")
        )
        return
    diagnostics.append(Diagnostic("rewrite_value", INFO, path, f"{text!r} -> {new_text!r}"))


def rewrite_toml(text: str, mapping: dict[str, str]) -> RewriteResult:
    try:
        document = tomlkit.parse(text)
    except TOMLKitError as error:
        return RewriteResult("toml", False, False, text, None, [Diagnostic("malformed_input", UNSAFE, "<document>", str(error))])

    control_text = tomlkit.dumps(document)
    if control_text != text:
        return RewriteResult(
            "toml", False, False, text, None,
            [Diagnostic("round_trip_fidelity_unsupported", UNSAFE, "<document>",
                        "unmodified control round-trip did not reproduce the source byte-for-byte")],
        )

    diagnostics: list[Diagnostic] = []
    guard = _CycleGuard()
    _toml_walk(document, mapping, "", diagnostics, guard)
    if any(d.severity == UNSAFE for d in diagnostics):
        return RewriteResult("toml", False, False, text, None, diagnostics)

    new_text = tomlkit.dumps(document)
    changed = new_text != text
    diagnostics.extend(_residual_and_new_reference_diagnostics(text, new_text, mapping))
    return RewriteResult("toml", True, changed, text, new_text, diagnostics)


