_YAML_INDENT_CANDIDATES = [(2, 2, 0), (2, 4, 2), (4, 4, 0), (4, 6, 2)]


def _build_yaml(mapping_indent: int, sequence_indent: int, offset: int) -> YAML:
    yaml = YAML(typ="rt")
    yaml.preserve_quotes = True
    yaml.width = 1 << 20  # do not introduce line-wrapping the source did not have
    yaml.indent(mapping=mapping_indent, sequence=sequence_indent, offset=offset)
    return yaml


def _yaml_dump(yaml: YAML, document: Any) -> str:
    buffer = io.StringIO()
    yaml.dump(document, buffer)
    return buffer.getvalue()


def _yaml_walk(node: Any, mapping: dict[str, str], path: str, diagnostics: list[Diagnostic], guard: _CycleGuard) -> None:
    if isinstance(node, TaggedScalar):
        diagnostics.append(Diagnostic("unsupported_tag", UNSAFE, path, f"unrecognised YAML tag {node.tag!r}; refusing to inspect its content"))
        return
    if guard.enter(node):
        diagnostics.append(Diagnostic("alias_cycle", UNSAFE, path, "cyclic structure detected while walking YAML document"))
        return
    if isinstance(node, dict):
        guard.push(node)
        for key in list(node.keys()):
            value = node[key]
            child_path = f"{path}.{key}" if path else str(key)
            if isinstance(value, str):
                _yaml_maybe_replace_leaf(node, key, value, mapping, child_path, diagnostics)
            else:
                _yaml_walk(value, mapping, child_path, diagnostics, guard)
        guard.pop(node)
    elif isinstance(node, list):
        guard.push(node)
        for index, value in enumerate(node):
            child_path = f"{path}[{index}]"
            if isinstance(value, str):
                _yaml_maybe_replace_leaf(node, index, value, mapping, child_path, diagnostics)
            else:
                _yaml_walk(value, mapping, child_path, diagnostics, guard)
        guard.pop(node)


def _yaml_maybe_replace_leaf(container: Any, key: Any, value: str, mapping: dict[str, str], path: str, diagnostics: list[Diagnostic]) -> None:
    new_value = value
    hit = False
    for old, new in mapping.items():
        if old in new_value:
            new_value = new_value.replace(old, new)
            hit = True
    if not hit:
        return
    container[key] = new_value
    diagnostics.append(Diagnostic("rewrite_value", INFO, path, f"{value!r} -> {new_value!r}"))


def _yaml_scalar_types_stable(before: Any, after: Any, path: str, diagnostics: list[Diagnostic]) -> None:
    """Re-parse-and-compare guard: every replaced leaf must still be a string after
    a full dump+reload cycle (defends against a plain scalar becoming ambiguous
    with a YAML core-schema bool/int/null on re-parse)."""
    if isinstance(before, dict) and isinstance(after, dict):
        for key in before.keys():
            if key in after:
                _yaml_scalar_types_stable(before[key], after[key], f"{path}.{key}", diagnostics)
    elif isinstance(before, list) and isinstance(after, list):
        for index, (b, a) in enumerate(zip(before, after)):
            _yaml_scalar_types_stable(b, a, f"{path}[{index}]", diagnostics)
    elif isinstance(before, str):
        if not isinstance(after, str):
            diagnostics.append(
                Diagnostic("type_changing_substitution", UNSAFE, path,
                           f"value became {type(after).__name__} instead of str after round-trip")
            )


def rewrite_yaml(text: str, mapping: dict[str, str]) -> RewriteResult:
    detected: tuple[int, int, int] | None = None
    document = None
    for candidate in _YAML_INDENT_CANDIDATES:
        yaml = _build_yaml(*candidate)
        try:
            candidate_document = yaml.load(text)
        except YAMLError as error:
            return RewriteResult("yaml", False, False, text, None, [Diagnostic("malformed_input", UNSAFE, "<document>", str(error))])
        control_text = _yaml_dump(yaml, candidate_document)
        if control_text == text:
            detected = candidate
            document = candidate_document
            break

    if detected is None:
        return RewriteResult(
            "yaml", False, False, text, None,
            [Diagnostic("round_trip_fidelity_unsupported", UNSAFE, "<document>",
                        "no candidate block-sequence indent profile reproduced the source byte-for-byte")],
        )

    diagnostics: list[Diagnostic] = []
    guard = _CycleGuard()
    _yaml_walk(document, mapping, "", diagnostics, guard)
    if any(d.severity == UNSAFE for d in diagnostics):
        return RewriteResult("yaml", False, False, text, None, diagnostics)

    yaml = _build_yaml(*detected)
    new_text = _yaml_dump(yaml, document)

    # Defence-in-depth: reload the produced text and confirm every scalar
    # that started as a plain python str is still a str (ruamel already
    # auto-quotes ambiguous plain scalars on dump; this proves it held).
    reloaded = yaml.load(new_text)
    original_document = _build_yaml(*detected).load(text)
    _yaml_scalar_types_stable(original_document, reloaded, "", diagnostics)
    if any(d.severity == UNSAFE for d in diagnostics):
        return RewriteResult("yaml", False, False, text, None, diagnostics)

    changed = new_text != text
    diagnostics.extend(_residual_and_new_reference_diagnostics(text, new_text, mapping))
    return RewriteResult("yaml", True, changed, text, new_text, diagnostics)


