def _json_duplicate_checking_hook(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    seen: dict[str, Any] = {}
    duplicates: list[str] = []
    for key, value in pairs:
        if key in seen:
            duplicates.append(key)
        seen[key] = value
    if duplicates:
        raise ValueError(f"duplicate key(s) in JSON object: {sorted(set(duplicates))}")
    return seen


def _detect_json_profile(text: str) -> tuple[int, bool, bool]:
    """Return (indent_width, ends_with_newline, ensure_ascii)."""
    indent_width = 2
    for line in text.splitlines():
        if line.startswith(" ") and line.strip():
            leading = len(line) - len(line.lstrip(" "))
            if leading:
                indent_width = leading
                break
    ends_with_newline = text.endswith("\n")
    ensure_ascii = "\\u" in text and not any(ord(ch) > 127 for ch in text)
    return indent_width, ends_with_newline, ensure_ascii


def _json_walk(node: Any, mapping: dict[str, str], path: str, diagnostics: list[Diagnostic], guard: _CycleGuard) -> Any:
    if guard.enter(node):
        diagnostics.append(Diagnostic("alias_cycle", UNSAFE, path, "cyclic structure detected while walking JSON document"))
        return node
    if isinstance(node, dict):
        guard.push(node)
        for key in list(node.keys()):
            value = node[key]
            child_path = f"{path}.{key}" if path else str(key)
            if isinstance(value, str):
                node[key] = _json_maybe_replace_leaf(value, mapping, child_path, diagnostics)
            else:
                _json_walk(value, mapping, child_path, diagnostics, guard)
        guard.pop(node)
    elif isinstance(node, list):
        guard.push(node)
        for index, value in enumerate(node):
            child_path = f"{path}[{index}]"
            if isinstance(value, str):
                node[index] = _json_maybe_replace_leaf(value, mapping, child_path, diagnostics)
            else:
                _json_walk(value, mapping, child_path, diagnostics, guard)
        guard.pop(node)
    return node


def _json_maybe_replace_leaf(value: str, mapping: dict[str, str], path: str, diagnostics: list[Diagnostic]) -> str:
    new_value = value
    hit = False
    for old, new in mapping.items():
        if old in new_value:
            new_value = new_value.replace(old, new)
            hit = True
    if hit:
        diagnostics.append(Diagnostic("rewrite_value", INFO, path, f"{value!r} -> {new_value!r}"))
    return new_value


def rewrite_json(text: str, mapping: dict[str, str]) -> RewriteResult:
    try:
        document = json.loads(text, object_pairs_hook=_json_duplicate_checking_hook)
    except json.JSONDecodeError as error:
        return RewriteResult("json", False, False, text, None, [Diagnostic("malformed_input", UNSAFE, "<document>", str(error))])
    except ValueError as error:
        return RewriteResult("json", False, False, text, None, [Diagnostic("duplicate_key", UNSAFE, "<document>", str(error))])

    indent_width, ends_with_newline, ensure_ascii = _detect_json_profile(text)

    def _dump(node: Any) -> str:
        rendered = json.dumps(node, indent=indent_width, ensure_ascii=ensure_ascii)
        return rendered + "\n" if ends_with_newline else rendered

    control_text = _dump(document)
    if control_text != text:
        return RewriteResult(
            "json", False, False, text, None,
            [Diagnostic("round_trip_fidelity_unsupported", UNSAFE, "<document>",
                        "no detected (indent, trailing-newline, ascii) profile reproduced the source byte-for-byte")],
        )

    diagnostics: list[Diagnostic] = []
    guard = _CycleGuard()
    document = _json_walk(document, mapping, "", diagnostics, guard)
    if any(d.severity == UNSAFE for d in diagnostics):
        return RewriteResult("json", False, False, text, None, diagnostics)

    new_text = _dump(document)
    changed = new_text != text
    diagnostics.extend(_residual_and_new_reference_diagnostics(text, new_text, mapping))
    return RewriteResult("json", True, changed, text, new_text, diagnostics)


